NAME = 'NorSMB: Studentmållagsbibelen frå 1921'
BOOK = 'Zephaniah'

CHAPTERS = {
    1: {
        1: 'Herrens ord som kom til Sefanja, son åt Kusi, son åt Gedalja, son åt Amarja, son åt Hizkia, i dei dagar då Josia Amonsson var konge i Juda.',
        2: 'Burt, ja burt vil eg taka alt frå jordi, segjer Herren.',
        3: 'Eg vil taka burt menneskje og dyr, taka burt fuglarne under himmelen og fiskarne i havet og støytesteinarne i lag med dei gudlause, og eg vil rydja menneski ut av jordi, segjer Herren.',
        4: 'Og eg vil retta ut handi mi mot Juda og alle deim som bur i Jerusalem, og eg vil rydja ut frå denne staden den siste leivning av Ba’al, namnet åt avgudsprestarne i lag med prestarne,',
        5: 'deim som på taki bed til himmelheren, deim som bed til og sver ved Herren og attpå sver ved Milkom,',
        6: 'og deim som hev vendt seg burt frå Herren, og deim som ikkje hev søkt Herren og ikkje spurt etter honom.',
        7: 'Ver stille for Herren, Herren! For Herrens dag er nær, Herren hev laga til eit slagtoffer, han hev vigt sine gjester.',
        8: 'Og på Herrens slagtofferdag vil eg heimsøkja hovdingarne og kongssønerne og alle som klæder seg i utanlands-klæde.',
        9: 'Og eg vil på den dagen heimsøkja alle deim som hoppar yver dørstokken, dei som fyller sin Herres hus med vald og svik.',
        10: 'På den dagen, segjer Herren, skal det høyrast skrik frå Fiskeporten, jammer frå Nybyen og stort brak frå høgderne.',
        11: 'Jamra, de som bur i Mortelen, for heile kræmerfolket er gjort til inkjes, og alle kjøpmenner utrudde.',
        12: 'Og på den same tidi vil eg ransaka Jerusalem med lykter og heimsøkja dei menneskje som ligg i ro på sin berm og segjer i sitt hjarta: «Herren gjer korkje godt eller vondt.»',
        13: 'Og eigedomen deira skal verta til herfang og husi deira til tjon. Hus skal dei byggja, men ikkje bu i deim, vinhagar skal dei planta, men ikkje drikka deira vin.',
        14: 'Nær er Herrens dag, den store. Han er nær og kjem med stor hast. Høyr! Det er Herrens dag! Sårt skrik då kjempa.',
        15: 'Ein vreide-dag er den dagen, ein dag med naud og trengsla, ein dag med øyding og audner, ein dag med myrker og dimma, ein dag med skyer og skodda,',
        16: 'ein dag med lurblåster og herrop mot dei faste byar og mot dei høge murtindar.',
        17: 'Då vil eg setja folk i slik angest, at dei gjeng der som blinde, for di dei hev synda mot Herren. Blodet deira skal verta burtslengt som mold, og kjøtet deira som møk.',
        18: 'Korkje sylvet eller gullet deira skal kunde berga deim på Herrens vreide-dag, når elden frå hans brennhug øyder all jordi; for han vil gjera ende, ja, ein brå ende på alle deim som bur på jordi.',
    },
    2: {
        1: 'Samla dykk og sansa dykk, du folk som ikkje blygjest!',
        2: 'fyrr rådgjerdi føder - som agner fer dagen fram - fyrr Herrens brennande vreide kjem yver dykk, fyrr Herrens vreide-dag kjem yver dykk.',
        3: 'Søk Herren alle de audmjuke i landet, som held lovi hans! Søk rettferd, søk audmykt! Kann henda vert de då livde på Herrens vreide-dag!',
        4: 'For Gaza skal verta folketomt, Askalon til ei øydemark, Asdod-folket skal jagast ut midt på ljose dagen og Ekron rykkjast upp med rot.',
        5: 'Usæle dei som bur i bygdi utmed havet, kretarfolket. Herrens ord er yver deg, Kana’an, Filistarland. Ja, eg vil leggja deg i øyde, so ingen skal bu i deg.',
        6: 'Og bygdi utmed havet skal liggja til hamnegang med gjætarbrunnar og sauegardar.',
        7: 'Og leivningen av Judas hus skal få bygdi til sin lut, der skal dei hava beite. I Askalon-husi skal dei liggja um kvelden, når Herren, deira Gud, ser til deim, og vender deira lagnad.',
        8: 'Eg hev høyrt svivyrdingi frå Moab og spottordi frå Ammons-borni, som dei hev svivyrdt mitt folk med og briska seg mot landet deira.',
        9: 'Difor, so visst som eg lever, segjer Herren, allhers drott, Israels Gud, skal det ganga Moab som Sodoma og Ammons-sønerne som Gomorra: Dei skal verta til netlemark, saltgruva og øydemark til æveleg tid. Resten av folket mitt skal plundra deim, leivningen av lyden min skal få deim til eiga.',
        10: 'Dette skal henda deim for deira storlæte, for di dei svivyrde og briska seg mot folket åt Herren, allhers drott.',
        11: 'Fæl skal Herren vera mot deim, for han skal øyda ut alle gudarne på jordi. Alle heidninglandi skal kasta seg ned for honom, kvar frå sin stad.',
        12: 'De og, ætiopar - gjenomstungne av sverdet mitt er dei.',
        13: 'Han retter ut handi mot nord og tyner Assur og gjer Nineve til ei øydemark, til turre heidi.',
        14: 'Hjorder skal lægra seg der inne, alle slag villdyr i flokk. Pelikan og bustyvel skal natta på sulehovudi der, fuglelåt høyrast i vindaugo, øyda bu på dørstokken, for cederpanelet hev han rive.',
        15: 'Dette er den jublande byen, som sat so trygt og sagde i sitt hjarta: «Eg og ingen annan!» Kor aud han er vorten, eit læger for villdyr! Kvar den som framum fer, blistrar og vinkar med handi.',
    },
    3: {
        1: 'Usæl han, den tråssuge og ureine, valdsbyen!',
        2: 'Han høyrer ikkje på røysti åt nokon, tek ikkje tukt. På Herren lit han ikkje, til sin Gud vil han ikkje koma.',
        3: 'Hovdingarne der inne er burande løver, domarane hans er som ulvar um kvelden; dei sparar inkje til morgondagen.',
        4: 'Profetarne hans er skrythalsar, trulause menner, prestarne vanhelgar det heilage, gjer vald mot lovi.',
        5: 'Herren er rettferdig der inne, gjer ikkje urett. Kvar morgon let han sin dom koma fram i ljoset, det glepp ikkje. Men den urettferdige kjenner ikkje skam.',
        6: 'Eg hev øydt ut folkeslag, deira murtindar vart nedbrotne. Eg gjorde gatorne deira aude, so ingen ferdast på deim; byarne deira vart herja, so dei er utan folk, utan ibuar.',
        7: 'Eg sagde: Berre du vil ottast meg, taka tukt, so skal bustaden din ikkje verta øydelagd med alt det som eg hev gjeve deg i varetekt. Like vel var dei uppsette på å lata alle sine gjerningar vera illverk.',
        8: 'Difor, bia på meg, segjer Herren, til den dagen eg ris upp til herfang. For det er min dom at eg samlar folki og stemner saman kongeriki, renner ut harmen min yver deim, all min brennande vreide; for elden av min brennhug skal øyda heile jordi.',
        9: 'For då vil eg gjeva folki nye, reine lippor, so dei kann kalla på Herrens namn og samheldigt tena honom.',
        10: 'Frå landet burtanfor elvarne i Ætiopia skal dei føra mine tilbedarar, mitt spreidde folk bera fram offer til meg.',
        11: 'På den dagen tarv du ikkje skjemmast ved alle gjerningarne dine, som du synda imot meg med; for då vil eg rydja burt frå deg deim som jublar so stolt i deg, og du skal ikkje meir gjera deg stor på mitt heilage fjell.',
        12: 'Men eg vil leiva i deg eit audmjukt og armt folk, og dei skal lita på Herrens namn.',
        13: 'Israels leivning skal ikkje gjera urett, dei skal ikkje tala lygn, og det skal ikkje finnast svikfull tunga i deira munn. Ja, dei skal beita og liggja i ro, utan at nokon skræmer deim.',
        14: 'Jubla, dotter Sion! Lyft upp fagnadrop, Israel! Gled deg og frygda deg av alt ditt hjarta, dotter Jerusalem.',
        15: 'Herren hev vend straffedomarne ifrå deg, rudt fienden din or vegen. Herren, Israels konge, er hjå deg. Du tarv ikkje meir ottast noko vondt.',
        16: 'På den dagen skal det segjast til Jerusalem: «Ottast ikkje, Sion, lat ikkje henderne siga!',
        17: 'Herren din Gud er hjå deg, ei kjempa som kann frelsa. Han gled seg yver deg med fagnad, han tegjer i sin kjærleik; han jublar i frygd yver deg.»',
        18: 'Eg samlar deim som med sorg hev vore utestengde frå høgtidsstemnorne; dei er frå deg. Vanæra tyngjer på deim.',
        19: 'Sjå, på den tidi vil eg taka på trælkarane dine, og eg vil frelsa dei halte og sanka saman dei burtdrivne og gjera deim til æra og gjetord yver heile jordi, der dei fyrr var vanæra.',
        20: 'På den tid let eg dykk koma heim att, på den tid sankar eg dykk, og eg vil gjera dykk til gjetord og æra millom alle folki på jordi, når eg vender lagnaden dykkar for augo på dykk, segjer Herren.',
    },
}
